import { expect } from "chai";
import { ethers } from "hardhat";
import type { Contract } from "ethers";

// Recorded lock txBytes from the real failed Sepolia lock
// GET https://prover.cc3-testnet.creditcoin.network/api/v1/proof-by-tx/1/0x944386aa6fcc969ac17d7223d9c1fe69169ae5b54a6ede108c7710883a56e93b
// Field txBytes, inlined as a fixture constant (no network calls from tests).
const LIVE_TXBYTES = "";

const EXPECTED_FROM = "0xe9eE885c5F70EDBd39fe7bD488E6503c32e33626";
const EXPECTED_TO = "0x14c5A97d895e148Fe84C676c02b127e49dB5feAa";
const EXPECTED_AMOUNT = 2000000000000000000n;
const EXPECTED_RECIPIENT = "0xe9eE885c5F70EDBd39fe7bD488E6503c32e33626";
const EXPECTED_NONCE = 82463816781879281029340671069982627780789254357879087259152547709878235164484n;
const STARS_LOCKED_SIG = ethers.id("StarsLocked(address,uint256,uint256,address)");
const SOURCE_CHAIN_KEY = 1n;
const PROVEN_HEIGHT = 11686603n;
const ZERO_HASH = ethers.ZeroHash;

describe("LiveBlobRegression", function () {
  it("decodes the recorded lock blob to the expected from/to/calldata plus StarsLocked log", async function () {
    const coder = ethers.AbiCoder.defaultAbiCoder();
    const decoded = coder.decode(["uint8", "bytes[]"], LIVE_TXBYTES) as unknown as [bigint, string[]];
    const txType = decoded[0];
    const chunks = decoded[1];
    expect(txType).to.equal(2n);
    expect(chunks.length).to.equal(3);
    const chunk0 = chunks[0] as string;
    const common = coder.decode(
      ["uint64", "uint64", "address", "bool", "address", "uint256", "bytes"],
      chunk0,
    ) as unknown as [bigint, bigint, string, boolean, string, bigint, string];
    const from = common[2];
    const toIsNull = common[3];
    const to = common[4];
    const value = common[5];
    const data = common[6];
    expect(toIsNull).to.equal(false);
    expect(from).to.equal(EXPECTED_FROM);
    expect(to).to.equal(EXPECTED_TO);
    expect(value).to.equal(0n);
    const selector = data.slice(0, 10);
    expect(selector.toLowerCase()).to.equal("0xd35cf790");
    const lockArgs = coder.decode(
      ["uint256", "uint256", "address"],
      "0x" + data.slice(10),
    ) as unknown as [bigint, bigint, string];
    expect(lockArgs[0]).to.equal(EXPECTED_AMOUNT);
    expect(lockArgs[1]).to.equal(EXPECTED_NONCE);
    expect(lockArgs[2]).to.equal(EXPECTED_RECIPIENT);
    const chunk2 = chunks[2] as string;
    const receipt = coder.decode(
      ["uint8", "uint64", "tuple(address addr,bytes32[] topics,bytes data)[]", "bytes"],
      chunk2,
    ) as unknown as [bigint, bigint, Array<[string, string[], string]>, string];
    expect(receipt[0]).to.equal(1n);
    expect(receipt[2].length).to.be.greaterThan(0);
    const starsLocked = receipt[2].filter((l) => l[1].length > 0 && l[1][0] === STARS_LOCKED_SIG);
    expect(starsLocked.length).to.be.greaterThan(0);
    const match = starsLocked.find((l) => l[0].toLowerCase() === EXPECTED_TO.toLowerCase());
    expect(match).to.not.equal(undefined);
  });

  it("executes the recorded lock blob onchain via the linked decoder library", async function () {
    const signers = await ethers.getSigners();
    const deployer = signers[0];
    if (deployer === undefined) throw new Error("missing signer");
    void deployer;
    const StarsCCFactory = await ethers.getContractFactory("OrbitStarsCC");
    const starsCC = await StarsCCFactory.deploy();
    await starsCC.waitForDeployment();
    const LeaderboardFactory = await ethers.getContractFactory("PixelOrbitLeaderboard");
    const leaderboard = await LeaderboardFactory.deploy();
    await leaderboard.waitForDeployment();
    const ProverFactory = await ethers.getContractFactory("MockBlockProver");
    const proverContract = await ProverFactory.deploy();
    await proverContract.waitForDeployment();
    const AscFactory = await ethers.getContractFactory("PixelOrbitASC");
    const ascContract = await AscFactory.deploy(
      await (proverContract as unknown as Contract).getAddress(),
      EXPECTED_TO,
      SOURCE_CHAIN_KEY,
      await (starsCC as unknown as Contract).getAddress(),
      await (leaderboard as unknown as Contract).getAddress(),
    );
    await ascContract.waitForDeployment();
    const asc = ascContract as unknown as Contract;
    await (starsCC as unknown as Contract).getFunction("setMinter")(await asc.getAddress());
    await (leaderboard as unknown as Contract).getFunction("setAsc")(await asc.getAddress());
    await expect(
      asc.getFunction("execute")(
        0,
        SOURCE_CHAIN_KEY,
        PROVEN_HEIGHT,
        LIVE_TXBYTES,
        ZERO_HASH,
        [],
        ZERO_HASH,
        [],
      ),
    )
      .to.emit(asc, "BridgeExecuted")
      .withArgs(EXPECTED_FROM, EXPECTED_RECIPIENT, EXPECTED_AMOUNT, EXPECTED_NONCE);
    expect(await (starsCC as unknown as Contract).getFunction("balanceOf")(EXPECTED_RECIPIENT)).to.equal(EXPECTED_AMOUNT);
  });
});
